rss.channel:
{{ site.title }}
{{ site.url | default: site.github.url | default: "https://" | append: site.github.owner_name | append: ".github.io/" }}
{{ site.description }}
{% for post in site.posts limit: 20 %}


  {{ post.title | xml_escape }}
  {{ post.url | absolute_url }}
  {{ post.date | date_to_rfc822 }}
  {{ post.excerpt | markdownify }}

{% endfor %}
